#!/usr/bin/env python3
"""Create attendees_clean.csv with the first occurrence of each email."""

import csv

INPUT_FILE = "attendees.csv"
OUTPUT_FILE = "attendees_clean.csv"


def main():
    with open(INPUT_FILE, "r", encoding="utf-8", newline="") as source, open(
        OUTPUT_FILE, "w", encoding="utf-8", newline=""
    ) as destination:
        reader = csv.DictReader(source)
        if reader.fieldnames is None:
            return

        writer = csv.DictWriter(destination, fieldnames=reader.fieldnames)
        writer.writeheader()

        seen_emails = set()
        for row in reader:
            email = row["email"]
            if email not in seen_emails:
                writer.writerow(row)
                seen_emails.add(email)


if __name__ == "__main__":
    main()
